local PerfumeBottleMaker = {}
local PRODUCTS = {
    glass_perfume_bottle = { name = "Steklena steklenička parfuma", glassCost = 2, time = 2, cost = 25, artistry = 40, prestige = 2, description = "Steklena steklenička za parfum." },
    painted_bottle = { name = "Poslikana steklenička", glassCost = 2, paintCost = 1, time = 3, cost = 55, artistry = 55, prestige = 4, happiness = 1, description = "Poslikana steklenička z barvami." },
    silver_capped_bottle = { name = "Srebrnopokrovna steklenička", glassCost = 2, silverCost = 1, paintCost = 1, time = 5, cost = 130, artistry = 70, prestige = 8, happiness = 2, description = "Steklenička s srebrnim pokrovom za plemiče." },
    silver_filigree_bottle = { name = "Srebrnofiligranska steklenička", glassCost = 2, silverCost = 1, goldCost = 1, paintCost = 1, time = 8, cost = 320, artistry = 82, prestige = 14, happiness = 3, description = "Steklenička s srebrno filigransko okras." },
    gold_capped_bottle = { name = "Zlatopokrovna steklenička", glassCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, paintCost = 1, time = 11, cost = 700, artistry = 92, prestige = 22, happiness = 5, description = "Steklenička z zlatim pokrovom za visoke plemiče." },
    royal_grand_bottle = { name = "Kraljevski veliki steklenička", glassCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, paintCost = 2, time = 16, cost = 1800, artistry = 100, prestige = 42, happiness = 10, description = "Velika kraljevska steklenička z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Steklenička delavnica", cost = { gold = 280, wood = 130, stone = 250 }, upkeep = 7, qualityBonus = 5 },
    glass_blowing_room = { name = "Steklopihačnica", cost = { gold = 950, wood = 250, stone = 450, glass = 8 }, upkeep = 23, qualityBonus = 18 },
    decorating_room = { name = "Okrasovalnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, paint = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_bottle_atelier = { name = "Kraljevski atelje stekleničk", cost = { gold = 9200, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 40 },
}
PerfumeBottleMaker.glassStock = 14; PerfumeBottleMaker.paintStock = 12; PerfumeBottleMaker.silverStock = 8; PerfumeBottleMaker.goldStock = 6; PerfumeBottleMaker.jewelStock = 6; PerfumeBottleMaker.pearlStock = 4
PerfumeBottleMaker.productStock = {}; PerfumeBottleMaker.buildings = {}; PerfumeBottleMaker.maker = nil; PerfumeBottleMaker.activeMaking = {}; PerfumeBottleMaker.totalProducts = 0; PerfumeBottleMaker.dayTimer = 0
function PerfumeBottleMaker.init() PerfumeBottleMaker.glassStock=14; PerfumeBottleMaker.paintStock=12; PerfumeBottleMaker.silverStock=8; PerfumeBottleMaker.goldStock=6; PerfumeBottleMaker.jewelStock=6; PerfumeBottleMaker.pearlStock=4; PerfumeBottleMaker.productStock={}; PerfumeBottleMaker.buildings={}; PerfumeBottleMaker.maker=nil; PerfumeBottleMaker.activeMaking={}; PerfumeBottleMaker.totalProducts=0; PerfumeBottleMaker.dayTimer=0; print("[PerfumeBottleMaker] Royal Perfume Bottle Maker System initialized (6 products, 4 buildings)") end
function PerfumeBottleMaker.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PerfumeBottleMaker.maker={name=n or ("Stekleničkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stekleničkar najet: %s (spretnost: %d)",PerfumeBottleMaker.maker.name,s),"success") end; return true end
function PerfumeBottleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PerfumeBottleMaker.build(id) local ok,e=PerfumeBottleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PerfumeBottleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PerfumeBottleMaker.getQualityBonus() local b=0; for _,bd in ipairs(PerfumeBottleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PerfumeBottleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and PerfumeBottleMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.paintCost and PerfumeBottleMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and PerfumeBottleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PerfumeBottleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PerfumeBottleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PerfumeBottleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PerfumeBottleMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PerfumeBottleMaker.maker then return false,"Potreben stekleničkar" end; return true end
function PerfumeBottleMaker.make(pt,qty) qty=qty or 1; local ok,e=PerfumeBottleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then PerfumeBottleMaker.glassStock=PerfumeBottleMaker.glassStock-d.glassCost*qty end; if d.paintCost then PerfumeBottleMaker.paintStock=PerfumeBottleMaker.paintStock-d.paintCost*qty end; if d.silverCost then PerfumeBottleMaker.silverStock=PerfumeBottleMaker.silverStock-d.silverCost*qty end; if d.goldCost then PerfumeBottleMaker.goldStock=PerfumeBottleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PerfumeBottleMaker.jewelStock=PerfumeBottleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PerfumeBottleMaker.pearlStock=PerfumeBottleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PerfumeBottleMaker.maker then t=math.max(1,t-math.floor(PerfumeBottleMaker.maker.skill/12)) end; table.insert(PerfumeBottleMaker.activeMaking,{id="perfumebottle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PerfumeBottleMaker.completeMaking(m) local q=1.0+(PerfumeBottleMaker.getQualityBonus()/100); if PerfumeBottleMaker.maker then q=q+(PerfumeBottleMaker.maker.skill/180) end; q=math.min(2.0,q); PerfumeBottleMaker.productStock[m.productType]=(PerfumeBottleMaker.productStock[m.productType] or 0)+m.quantity; PerfumeBottleMaker.totalProducts=PerfumeBottleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PerfumeBottleMaker.maker then PerfumeBottleMaker.maker.itemsMade=PerfumeBottleMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then PerfumeBottleMaker.maker.skill=math.min(100,PerfumeBottleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklenička izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"perfumebottle.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function PerfumeBottleMaker.update(dt) if not _G.state then return end; PerfumeBottleMaker.dayTimer=PerfumeBottleMaker.dayTimer+dt; if PerfumeBottleMaker.dayTimer>=30 then PerfumeBottleMaker.dayTimer=0; for i=#PerfumeBottleMaker.activeMaking,1,-1 do local m=PerfumeBottleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PerfumeBottleMaker.completeMaking(m); table.remove(PerfumeBottleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PerfumeBottleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PerfumeBottleMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PerfumeBottleMaker.getStats() return {glassStock=PerfumeBottleMaker.glassStock,paintStock=PerfumeBottleMaker.paintStock,silverStock=PerfumeBottleMaker.silverStock,goldStock=PerfumeBottleMaker.goldStock,jewelStock=PerfumeBottleMaker.jewelStock,pearlStock=PerfumeBottleMaker.pearlStock,productStock=PerfumeBottleMaker.productStock,numBuildings=#PerfumeBottleMaker.buildings,hasMaker=PerfumeBottleMaker.maker~=nil,makerName=PerfumeBottleMaker.maker and PerfumeBottleMaker.maker.name or "—",makerSkill=PerfumeBottleMaker.maker and PerfumeBottleMaker.maker.skill or 0,activeMaking=#PerfumeBottleMaker.activeMaking,totalProducts=PerfumeBottleMaker.totalProducts} end
return PerfumeBottleMaker
